import React, { useState, useRef } from 'react';
import {
  View,
  Text,
  TouchableOpacity,
  StyleSheet,
  Modal,
  Alert,
  ActivityIndicator,
  Animated,
  ScrollView,
} from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import * as Clipboard from 'expo-clipboard';
import * as Sharing from 'expo-sharing';
import { COLORS, FONTS } from '../lib/constants';
import { useApp } from '../contexts/AppContext';
import { clearApiKey } from '../lib/api';
import { getSessionExportText } from '../lib/database';

interface Props {
  visible: boolean;
  onClose: () => void;
}

export default function AdminMenu({ visible, onClose }: Props) {
  const { state, toggleDebugMode, resetTrackers, doFullReset } = useApp();
  const [fullResetStep, setFullResetStep] = useState(0); // 0=idle, 1=warned, 2=holding
  const [exportLoading, setExportLoading] = useState(false);
  const holdProgress = useRef(new Animated.Value(0)).current;
  const holdTimeout = useRef<NodeJS.Timeout>();

  function handleResetSession() {
    Alert.alert(
      'Reset Current Session',
      'Clear this session\'s events and reset trackers to starting values? All session history is kept.',
      [
        { text: 'Cancel', style: 'cancel' },
        {
          text: 'Reset Session',
          style: 'destructive',
          onPress: async () => {
            await resetTrackers();
            onClose();
          },
        },
      ]
    );
  }

  function handleFullReset() {
    if (fullResetStep === 0) {
      setFullResetStep(1);
      return;
    }
    // Step 2 is handled by hold gesture below
  }

  function startHold() {
    if (fullResetStep !== 1) return;
    holdProgress.setValue(0);
    Animated.timing(holdProgress, {
      toValue: 1,
      duration: 2000,
      useNativeDriver: false,
    }).start(({ finished }) => {
      if (finished) {
        doFullReset().then(() => {
          setFullResetStep(0);
          holdProgress.setValue(0);
          onClose();
        });
      }
    });
  }

  function endHold() {
    holdProgress.stopAnimation();
    holdProgress.setValue(0);
  }

  function handleResetTrackers() {
    Alert.alert(
      'Reset Trackers',
      'Reset all four trackers to starting values? Events and narrative are kept.',
      [
        { text: 'Cancel', style: 'cancel' },
        {
          text: 'Reset',
          style: 'destructive',
          onPress: () => resetTrackers(),
        },
      ]
    );
  }

  async function handleExport() {
    if (!state.currentSessionId) return;
    setExportLoading(true);
    try {
      const text = await getSessionExportText(state.currentSessionId);
      await Clipboard.setStringAsync(text);
      Alert.alert('Copied', 'Session log copied to clipboard.');
    } catch {
      Alert.alert('Error', 'Failed to export session log.');
    } finally {
      setExportLoading(false);
    }
  }

  async function handleApiKey() {
    Alert.alert(
      'Reset API Key',
      'This will clear your stored API key and show the setup screen.',
      [
        { text: 'Cancel', style: 'cancel' },
        {
          text: 'Reset Key',
          style: 'destructive',
          onPress: async () => {
            await clearApiKey();
            onClose();
            // The root navigator will detect missing key and show setup screen
            Alert.alert('Key cleared', 'Restart the app to enter a new API key.');
          },
        },
      ]
    );
  }

  const barWidth = holdProgress.interpolate({
    inputRange: [0, 1],
    outputRange: ['0%', '100%'],
  });

  return (
    <Modal
      visible={visible}
      transparent
      animationType="fade"
      onRequestClose={() => { setFullResetStep(0); onClose(); }}
    >
      <TouchableOpacity
        style={styles.overlay}
        onPress={() => { setFullResetStep(0); onClose(); }}
        activeOpacity={1}
      >
        <TouchableOpacity activeOpacity={1} style={styles.panel}>
          <View style={styles.panelHeader}>
            <Text style={styles.panelTitle}>ADMIN</Text>
            <TouchableOpacity onPress={() => { setFullResetStep(0); onClose(); }} hitSlop={{ top: 8, right: 8, bottom: 8, left: 8 }}>
              <Ionicons name="close" size={18} color={COLORS.textFaint} />
            </TouchableOpacity>
          </View>

          <ScrollView>
            <MenuItem
              icon="refresh-outline"
              label="Reset current session"
              sublabel="Clears events, resets trackers. Keeps history."
              onPress={handleResetSession}
            />

            <MenuItem
              icon="pencil-outline"
              label="Reset trackers only"
              sublabel="Returns four values to start. Events kept."
              onPress={handleResetTrackers}
            />

            <MenuItem
              icon={exportLoading ? undefined : 'copy-outline'}
              label="Export session log"
              sublabel="Copy this session's narrative to clipboard."
              onPress={handleExport}
              loading={exportLoading}
            />

            <MenuItem
              icon="key-outline"
              label="API key"
              sublabel="Update without reinstalling."
              onPress={handleApiKey}
            />

            <MenuItem
              icon={state.debugMode ? 'eye-off-outline' : 'eye-outline'}
              label={state.debugMode ? 'Disable tracker debug' : 'Enable tracker debug'}
              sublabel={state.debugMode ? 'Hide tracker numbers.' : 'Show tracker values numerically.'}
              onPress={toggleDebugMode}
            />

            <View style={styles.divider} />

            {/* Full reset — two step */}
            {fullResetStep === 0 && (
              <MenuItem
                icon="trash-outline"
                label="Full reset"
                sublabel="Wipes everything. Cannot be undone."
                onPress={handleFullReset}
                danger
              />
            )}

            {fullResetStep === 1 && (
              <View style={styles.fullResetWarning}>
                <Text style={styles.fullResetWarningText}>
                  This deletes all events, sessions, clues, and the Mara thread. Everything. Hold the button for 2 seconds to confirm.
                </Text>
                <View style={styles.holdButtonContainer}>
                  <TouchableOpacity
                    style={styles.holdButton}
                    onPressIn={startHold}
                    onPressOut={endHold}
                    activeOpacity={0.9}
                  >
                    <Animated.View style={[styles.holdProgress, { width: barWidth }]} />
                    <Text style={styles.holdButtonText}>HOLD TO ERASE EVERYTHING</Text>
                  </TouchableOpacity>
                </View>
                <TouchableOpacity onPress={() => setFullResetStep(0)}>
                  <Text style={styles.cancelText}>Cancel</Text>
                </TouchableOpacity>
              </View>
            )}
          </ScrollView>
        </TouchableOpacity>
      </TouchableOpacity>
    </Modal>
  );
}

function MenuItem({
  icon,
  label,
  sublabel,
  onPress,
  danger,
  loading,
}: {
  icon?: string;
  label: string;
  sublabel: string;
  onPress: () => void;
  danger?: boolean;
  loading?: boolean;
}) {
  return (
    <TouchableOpacity style={styles.menuItem} onPress={onPress} activeOpacity={0.7}>
      <View style={styles.menuItemIcon}>
        {loading
          ? <ActivityIndicator size="small" color={COLORS.goldDim} />
          : icon ? <Ionicons name={icon as any} size={18} color={danger ? COLORS.red : COLORS.goldDim} /> : null
        }
      </View>
      <View style={styles.menuItemText}>
        <Text style={[styles.menuItemLabel, danger && styles.menuItemLabelDanger]}>{label}</Text>
        <Text style={styles.menuItemSublabel}>{sublabel}</Text>
      </View>
    </TouchableOpacity>
  );
}

