import React, { useEffect, useRef, useState } from 'react';
import { View, Text, TouchableOpacity, StyleSheet, Animated, Easing } from 'react-native';
import Svg, { Path, G, Line, Text as SvgText } from 'react-native-svg';
import { COLORS, FONTS } from '../lib/constants';

// Six behavioral states — observable, performable behaviors
const STATES = [
  { key: 'charming',  label: 'CHARMING',  desc: 'mask working',          angle: -90  },
  { key: 'volatile',  label: 'VOLATILE',  desc: 'magic at surface',      angle: -30  },
  { key: 'reckless',  label: 'RECKLESS',  desc: 'reaching badly',        angle:  30  },
  { key: 'withdrawn', label: 'WITHDRAWN', desc: 'not really there',      angle:  90  },
  { key: 'guarded',   label: 'GUARDED',   desc: 'watching every exit',   angle: 150  },
  { key: 'present',   label: 'PRESENT',   desc: 'actually here',         angle: 210  },
] as const;

type StateKey = typeof STATES[number]['key'];
type GlyphValues = Record<StateKey, number>;

// Tracker → glyph state mapping
function computeValues(mask: number, dagger: number, bottle: number, wound: number): GlyphValues {
  return {
    charming:  mask / 100,
    volatile:  dagger / 100,
    reckless:  bottle / 100,
    withdrawn: (100 - mask) / 100,
    guarded:   (wound * 0.6 + dagger * 0.4) / 100,
    present:   (100 - wound) / 100,
  };
}

// Pre-baked irregularities — makes the outer ring imperfect and organic
const RING_JITTER = [0.97, 1.03, 0.98, 1.01, 0.96, 1.02];

function degToRad(deg: number): number {
  return (deg * Math.PI) / 180;
}

function polarToCart(cx: number, cy: number, r: number, angleDeg: number) {
  const rad = degToRad(angleDeg);
  return { x: cx + r * Math.cos(rad), y: cy + r * Math.sin(rad) };
}

// Catmull-Rom spline through closed polygon — organic, slightly bowed
function buildSmoothPath(pts: { x: number; y: number }[]): string {
  const n = pts.length;
  if (n < 3) return '';
  const t = 0.4;
  let d = `M ${pts[0].x.toFixed(1)} ${pts[0].y.toFixed(1)}`;
  for (let i = 0; i < n; i++) {
    const p0 = pts[(i - 1 + n) % n];
    const p1 = pts[i];
    const p2 = pts[(i + 1) % n];
    const p3 = pts[(i + 2) % n];
    const cp1x = p1.x + (p2.x - p0.x) * t / 2;
    const cp1y = p1.y + (p2.y - p0.y) * t / 2;
    const cp2x = p2.x - (p3.x - p1.x) * t / 2;
    const cp2y = p2.y - (p3.y - p1.y) * t / 2;
    d += ` C ${cp1x.toFixed(1)} ${cp1y.toFixed(1)}, ${cp2x.toFixed(1)} ${cp2y.toFixed(1)}, ${p2.x.toFixed(1)} ${p2.y.toFixed(1)}`;
  }
  return d + ' Z';
}

// Fill color: muted amber → deep crimson as max intensity rises
function fillColor(maxVal: number): string {
  const r = Math.round(201 - maxVal * 65);
  const g = Math.round(168 - maxVal * 128);
  const b = Math.round(76  - maxVal * 44);
  const a = (0.15 + maxVal * 0.32).toFixed(2);
  return `rgba(${r},${g},${b},${a})`;
}

interface Props {
  mask: number;
  dagger: number;
  bottle: number;
  wound: number;
  maskFlavor: string;
  daggerFlavor: string;
  bottleFlavor: string;
  woundFlavor: string;
  size: number;
}

export default function ArcaneGlyph({
  mask, dagger, bottle, wound,
  maskFlavor, daggerFlavor, bottleFlavor, woundFlavor,
  size,
}: Props) {
  const flavorMap: Record<StateKey, string> = {
    charming:  maskFlavor,
    volatile:  daggerFlavor,
    reckless:  bottleFlavor,
    withdrawn: maskFlavor,
    guarded:   woundFlavor,
    present:   woundFlavor,
  };

  const init = computeValues(mask, dagger, bottle, wound);
  const [vals, setVals] = useState<GlyphValues>(init);
  const [tooltip, setTooltip] = useState<{ key: StateKey; text: string } | null>(null);

  // One Animated.Value per state — drives SVG on every frame
  const av = useRef<Record<StateKey, Animated.Value>>({
    charming:  new Animated.Value(init.charming),
    volatile:  new Animated.Value(init.volatile),
    reckless:  new Animated.Value(init.reckless),
    withdrawn: new Animated.Value(init.withdrawn),
    guarded:   new Animated.Value(init.guarded),
    present:   new Animated.Value(init.present),
  });

  // Attach listeners once — update render state on every animation tick
  useEffect(() => {
    const ids: Partial<Record<StateKey, string>> = {};
    (Object.keys(av.current) as StateKey[]).forEach(k => {
      ids[k] = av.current[k].addListener(({ value }) =>
        setVals(prev => ({ ...prev, [k]: value }))
      );
    });
    return () => {
      (Object.keys(av.current) as StateKey[]).forEach(k => {
        if (ids[k]) av.current[k].removeListener(ids[k]!);
      });
    };
  }, []);

  // Animate to new values on tracker change
  useEffect(() => {
    const next = computeValues(mask, dagger, bottle, wound);
    Animated.parallel(
      (Object.keys(next) as StateKey[]).map(k =>
        Animated.timing(av.current[k], {
          toValue: next[k],
          duration: 600,
          easing: Easing.inOut(Easing.ease),
          useNativeDriver: false,
        })
      )
    ).start();
  }, [mask, dagger, bottle, wound]);

  // Geometry
  const cx = size / 2;
  const cy = size / 2;
  const outerR   = size * 0.295;        // outer ring radius
  const glyphMaxR = outerR * 0.96;      // data point max radius (just inside ring)
  const innerMinR = size * 0.03;        // minimum so glyph never collapses to a dot
  const labelR    = size * 0.405;       // label text center radius
  const gridMidR  = outerR * 0.5;       // neutral-state reference ring (50%)

  const nameFontSize = Math.max(6, Math.round(size * 0.026));
  const descFontSize = Math.max(5, Math.round(size * 0.019));
  const diamondD     = Math.max(3, Math.round(size * 0.019));

  // Glyph polygon — expands/contracts as vals change
  const glyphPts = STATES.map(s => {
    const r = innerMinR + vals[s.key] * (glyphMaxR - innerMinR);
    return polarToCart(cx, cy, r, s.angle);
  });

  // Outer ring — irregular
  const ringPts = STATES.map((s, i) =>
    polarToCart(cx, cy, outerR * RING_JITTER[i], s.angle)
  );

  // Neutral reference ring at 50%
  const gridPts = STATES.map((s, i) =>
    polarToCart(cx, cy, gridMidR * RING_JITTER[i], s.angle)
  );

  const glyphPath = buildSmoothPath(glyphPts);
  const ringPath  = buildSmoothPath(ringPts);
  const gridPath  = buildSmoothPath(gridPts);

  const maxVal = Math.max(...(Object.values(vals) as number[]));
  const fill = fillColor(maxVal);

  // Dominant state = highest value
  const dominantKey = (Object.entries(vals) as [StateKey, number][])
    .reduce((a, b) => b[1] > a[1] ? b : a)[0];

  // Text anchor logic based on angle position
  function anchor(angle: number): 'middle' | 'start' | 'end' {
    const a = ((angle % 360) + 360) % 360;
    if (a === 270 || a === 90) return 'middle';
    if (a < 270 && a > 90) return 'end';
    return 'start';
  }

  // Name dy: push up from top, push down from bottom, center on sides
  function nameDy(angle: number): number {
    const a = ((angle % 360) + 360) % 360;
    if (a === 270) return -nameFontSize * 0.5;  // above
    if (a === 90)  return  nameFontSize * 1.2;  // below
    return nameFontSize * 0.35;                  // vertically centered
  }

  return (
    <View style={{ width: size, height: size }}>
      <Svg width={size} height={size}>
        {/* Spoke lines center → ring */}
        {STATES.map((s, i) => {
          const end = polarToCart(cx, cy, outerR * RING_JITTER[i], s.angle);
          return (
            <Line
              key={`spoke-${i}`}
              x1={cx} y1={cy} x2={end.x} y2={end.y}
              stroke={COLORS.goldFaint}
              strokeWidth={0.6}
              strokeOpacity={0.55}
            />
          );
        })}

        {/* Neutral 50% reference ring — dashed */}
        <Path
          d={gridPath}
          stroke={COLORS.goldFaint}
          strokeWidth={0.6}
          strokeOpacity={0.45}
          strokeDasharray="2 3"
          fill="none"
        />

        {/* Outer ring — slightly irregular */}
        <Path
          d={ringPath}
          stroke={COLORS.goldDim}
          strokeWidth={0.9}
          strokeOpacity={0.6}
          fill="none"
        />

        {/* Filled glyph area */}
        <Path
          d={glyphPath}
          fill={fill}
          stroke={COLORS.gold}
          strokeWidth={1.4}
          strokeOpacity={0.88}
        />

        {/* Diamond markers at each data point */}
        {glyphPts.map((pt, i) => {
          const d = diamondD;
          const dp = `M ${pt.x.toFixed(1)} ${(pt.y - d).toFixed(1)} L ${(pt.x + d).toFixed(1)} ${pt.y.toFixed(1)} L ${pt.x.toFixed(1)} ${(pt.y + d).toFixed(1)} L ${(pt.x - d).toFixed(1)} ${pt.y.toFixed(1)} Z`;
          return (
            <Path
              key={`diamond-${i}`}
              d={dp}
              fill={COLORS.gold}
              fillOpacity={0.92}
            />
          );
        })}

        {/* State labels — outside outer ring */}
        {STATES.map((s, i) => {
          const pos = polarToCart(cx, cy, labelR, s.angle);
          const anc = anchor(s.angle);
          const nd  = nameDy(s.angle);
          const isActive = s.key === dominantKey;
          return (
            <G key={`lbl-${i}`}>
              <SvgText
                x={pos.x}
                y={pos.y + nd}
                textAnchor={anc}
                fontFamily={FONTS.header}
                fontSize={nameFontSize}
                fill={isActive ? COLORS.gold : COLORS.goldDim}
                letterSpacing={0.8}
              >
                {s.label}
              </SvgText>
              <SvgText
                x={pos.x}
                y={pos.y + nd + nameFontSize + 2}
                textAnchor={anc}
                fontFamily={FONTS.body}
                fontSize={descFontSize}
                fill={isActive ? COLORS.textDim : COLORS.textFaint}
              >
                {s.desc}
              </SvgText>
            </G>
          );
        })}
      </Svg>

      {/* Tap zones at label positions — fixed, not animated */}
      {STATES.map((s, i) => {
        const pos = polarToCart(cx, cy, labelR, s.angle);
        const zone = Math.max(36, nameFontSize * 4);
        return (
          <TouchableOpacity
            key={`zone-${i}`}
            style={{
              position: 'absolute',
              left: pos.x - zone / 2,
              top: pos.y - zone / 2,
              width: zone,
              height: zone,
            }}
            onPress={() =>
              setTooltip(prev =>
                prev?.key === s.key
                  ? null
                  : { key: s.key, text: flavorMap[s.key] }
              )
            }
            activeOpacity={0.6}
          />
        );
      })}

      {/* Tooltip backdrop — tap outside to dismiss */}
      {tooltip && (
        <TouchableOpacity
          style={StyleSheet.absoluteFill}
          onPress={() => setTooltip(null)}
          activeOpacity={1}
        />
      )}

      {/* Tooltip card — pinned near bottom of glyph */}
      {tooltip && (
        <View style={[styles.tooltip, { top: cy + outerR + 8 }]} pointerEvents="none">
          <Text style={styles.tooltipLabel}>{tooltip.key.toUpperCase()}</Text>
          <Text style={styles.tooltipText}>{tooltip.text}</Text>
        </View>
      )}
    </View>
  );
}

const styles = StyleSheet.create({
  tooltip: {
    position: 'absolute',
    left: 12,
    right: 12,
    backgroundColor: COLORS.surface2,
    borderWidth: 1,
    borderColor: COLORS.goldDim,
    paddingVertical: 10,
    paddingHorizontal: 14,
    gap: 4,
  },
  tooltipLabel: {
    fontFamily: FONTS.header,
    fontSize: 8,
    color: COLORS.goldDim,
    letterSpacing: 3,
  },
  tooltipText: {
    fontFamily: FONTS.body,
    fontSize: 13,
    color: COLORS.text,
    lineHeight: 20,
  },
});
