import React, { useState } from 'react';
import {
  View,
  Text,
  TextInput,
  TouchableOpacity,
  StyleSheet,
  ActivityIndicator,
  KeyboardAvoidingView,
  Platform,
  ScrollView,
  Alert,
} from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';
import { COLORS, FONTS } from '../lib/constants';
import { saveApiKey } from '../lib/api';

interface Props {
  onComplete: () => void;
}

export default function SetupScreen({ onComplete }: Props) {
  const [key, setKey] = useState('');
  const [loading, setLoading] = useState(false);

  async function handleConfirm() {
    const trimmed = key.trim();
    if (!trimmed.startsWith('sk-ant-')) {
      Alert.alert('Invalid Key', 'Anthropic API keys begin with sk-ant-');
      return;
    }
    setLoading(true);
    try {
      await saveApiKey(trimmed);
      onComplete();
    } catch {
      Alert.alert('Error', 'Failed to store API key. Please try again.');
    } finally {
      setLoading(false);
    }
  }

  return (
    <SafeAreaView style={styles.safe}>
      <KeyboardAvoidingView
        style={styles.flex}
        behavior={Platform.OS === 'ios' ? 'padding' : 'height'}
      >
        <ScrollView
          contentContainerStyle={styles.container}
          keyboardShouldPersistTaps="handled"
        >
          <View style={styles.titleBlock}>
            <Text style={styles.title}>LUCIEN</Text>
            <View style={styles.divider} />
            <Text style={styles.subtitle}>Vale</Text>
          </View>

          <View style={styles.bodyBlock}>
            <Text style={styles.bodyText}>
              Enter your Anthropic API key to begin. The key is stored securely on this device
              and never leaves it.
            </Text>
            <Text style={styles.bodyTextItalic}>
              He's been here before — waiting on a threshold, deciding whether to step through.
            </Text>
          </View>

          <View style={styles.inputBlock}>
            <Text style={styles.inputLabel}>ANTHROPIC API KEY</Text>
            <TextInput
              style={styles.input}
              value={key}
              onChangeText={setKey}
              placeholder="sk-ant-..."
              placeholderTextColor={COLORS.textFaint}
              autoCapitalize="none"
              autoCorrect={false}
              secureTextEntry
              returnKeyType="done"
              onSubmitEditing={handleConfirm}
            />
          </View>

          <TouchableOpacity
            style={[styles.button, !key.trim() && styles.buttonDisabled]}
            onPress={handleConfirm}
            disabled={!key.trim() || loading}
            activeOpacity={0.75}
          >
            {loading
              ? <ActivityIndicator color={COLORS.background} />
              : <Text style={styles.buttonText}>ENTER</Text>
            }
          </TouchableOpacity>
        </ScrollView>
      </KeyboardAvoidingView>
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  safe: {
    flex: 1,
    backgroundColor: COLORS.background,
  },
  flex: { flex: 1 },
  container: {
    flexGrow: 1,
    justifyContent: 'center',
    paddingHorizontal: 32,
    paddingVertical: 48,
  },
  titleBlock: {
    alignItems: 'center',
    marginBottom: 48,
  },
  title: {
    fontFamily: FONTS.headerBold,
    fontSize: 42,
    color: COLORS.gold,
    letterSpacing: 12,
  },
  divider: {
    width: 60,
    height: 1,
    backgroundColor: COLORS.goldDim,
    marginVertical: 12,
  },
  subtitle: {
    fontFamily: FONTS.headerLight,
    fontSize: 18,
    color: COLORS.textDim,
    letterSpacing: 6,
  },
  bodyBlock: {
    marginBottom: 40,
    gap: 12,
  },
  bodyText: {
    fontFamily: FONTS.body,
    fontSize: 16,
    color: COLORS.textDim,
    textAlign: 'center',
    lineHeight: 24,
  },
  bodyTextItalic: {
    fontFamily: FONTS.bodyItalic,
    fontSize: 15,
    color: COLORS.textFaint,
    textAlign: 'center',
    lineHeight: 22,
  },
  inputBlock: {
    marginBottom: 32,
  },
  inputLabel: {
    fontFamily: FONTS.header,
    fontSize: 11,
    color: COLORS.goldDim,
    letterSpacing: 3,
    marginBottom: 10,
  },
  input: {
    borderWidth: 1,
    borderColor: COLORS.border,
    backgroundColor: COLORS.surface,
    color: COLORS.text,
    fontFamily: FONTS.body,
    fontSize: 15,
    paddingHorizontal: 16,
    paddingVertical: 14,
    borderRadius: 2,
  },
  button: {
    backgroundColor: COLORS.gold,
    paddingVertical: 16,
    alignItems: 'center',
    borderRadius: 2,
  },
  buttonDisabled: {
    backgroundColor: COLORS.goldFaint,
  },
  buttonText: {
    fontFamily: FONTS.header,
    fontSize: 13,
    color: COLORS.background,
    letterSpacing: 4,
  },
});
